412	        Claim claim = claims.findForUpdate(id, sheetId)
413	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
414	        if (!roles.may(sheetId, user, "settle")) {
415	            throw new ClaimActionForbiddenException(id, user, "settle");
416	        }
417	        if (user.equals(claim.getOpenedBy())) {
418	            throw new ClaimSettledByOpenerException(id, user, "opened");
419	        }
420	        if (user.equals(claim.getEditedBy())) {
421	            throw new ClaimSettledByOpenerException(id, user, "last edited");
422	        }
423	        if (claim.getStatus() == ClaimStatus.OPEN) {
424	            Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
425	                    .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
426	            requireProof(sheetId, person, claim);
427	        }
428	        Claim part = split(sheetId, user, id, amount);
429	        return changeStatus(sheetId, user, part.getId(), ClaimStatus.SETTLED, null, null, true, null);
430	    }
