478	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status, String voidReason,
479	            LongSupplier batch, boolean judgedOnOriginal, DueThen asOf) {
480	        Claim claim = claims.findForUpdate(id, sheetId)
481	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
482	        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
483	        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
484	            throw new ClaimStatusException(id, claim.getStatus(), status);
485	        }
486	        // The sheet's permission matrix decides which roles may open, settle or void.
487	        String action = switch (status) {
488	            case OPEN -> "open";
489	            case SETTLED -> "settle";
490	            case VOID -> "void";
491	            case DRAFT, PENDING, DELETED, REVIEW -> throw new ClaimStatusException(id, claim.getStatus(), status);
492	        };
493	        if (!roles.may(sheetId, user, action)) {
494	            throw new ClaimActionForbiddenException(id, user, action);
495	        }
496	        if (voidsSettled) {
497	            requireSettledVoidable(sheetId, user, claim);
498	        }
499	        periods.requireOpen(sheetId, claim.getDueBy());
500	        String reason = status == ClaimStatus.VOID ? requireVoidReason(sheetId, id, voidReason) : null;
501	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
502	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
503	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
504	        }
505	        // Four eyes: whoever opened or last edited a claim cannot also settle it.
506	        // A part-settle judges four eyes and proof on the claim it split from, not on the new claim.
507	        if (status == ClaimStatus.SETTLED && !judgedOnOriginal && user.equals(claim.getOpenedBy())) {
508	            throw new ClaimSettledByOpenerException(id, user, "opened");
509	        }
510	        if (status == ClaimStatus.SETTLED && !judgedOnOriginal && user.equals(claim.getEditedBy())) {
511	            throw new ClaimSettledByOpenerException(id, user, "last edited");
512	        }
513	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
514	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
515	        if (status == ClaimStatus.SETTLED && !judgedOnOriginal) {
516	            requireProof(sheetId, person, claim);
517	        }
518	        if (status == ClaimStatus.OPEN) {
519	            requireUnflagged(sheetId, user, person, claim);
520	            requireNote(sheetId, person, claim);
521	            requireUnderCap(sheetId, claim);
522	            // A claim whose due is above the review threshold on its date waits for a steward's review instead.
523	            if (needsReview(sheetId, person, claim)) {
524	                status = ClaimStatus.REVIEW;
525	            }
526	        }
527	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
528	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
529	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
530	            Sheet sheet = settings.get(sheetId);
531	            BigDecimal limit = sheet.clerkLimitFor(person.gradeOn(sheet.getToday()));
532	            BigDecimal due = asOf != null ? asOf.due()
533	                    : liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
534	            if (limit != null && due != null && due.compareTo(limit) > 0) {
535	                status = ClaimStatus.PENDING;
536	            }
537	        }
538	        RollupService.Snapshot before = rollup.snapshot(sheetId);
539	        String due = status == ClaimStatus.SETTLED && asOf != null ? settleAt(claim, asOf)
540	                : status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
541	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
542	        claim.setStatus(status);
543	        if (status == ClaimStatus.VOID) {
544	            claim.setVoidReason(reason);
545	        }
546	        // Settled one at a time, a claim carries no batch; settled by a bulk settle, it carries that batch's number.
547	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING) {
548	            claim.setSettleBatch(batch == null ? null : batch.getAsLong());
549	        }
550	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
551	        String number = claim.getNumber();
552	        if (status == ClaimStatus.OPEN) {
553	            number = nextNumber(sheetId, claim.getDueBy());
554	            claim.setNumber(number);
555	            claim.setOpenedBy(user);
556	        }
557	        // Sent to REVIEW, it records who opened it and its review day but takes no number until it is reviewed.
558	        if (status == ClaimStatus.REVIEW) {
559	            claim.setOpenedBy(user);
560	            claim.setReviewOn(sheets.today(sheetId));
561	        }
562	        Claim saved = claims.saveAndFlush(claim);
563	        log(sheetId, user, person, saved);
564	        String event = switch (status) {
565	            case OPEN -> "CLAIM_OPENED";
566	            case REVIEW -> "CLAIM_REVIEW";
567	            case PENDING -> "CLAIM_PENDING";
568	            case SETTLED -> "CLAIM_SETTLED";
569	            case VOID -> "CLAIM_VOIDED";
570	            case DRAFT, DELETED -> throw new IllegalStateException();
571	        };
572	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
573	                + (reason == null ? "" : " reason=" + reason));
574	        if (status == ClaimStatus.SETTLED) {
575	            watches.notifyWatchers(sheetId, user, person, number);
576	        }
577	        rollup.recordChanges(sheetId, user, before);
578	        return saved;
579	    }
