598	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
599	        RollupService.Snapshot before = rollup.snapshot(sheetId);
600	        claim.setStatus(ClaimStatus.DELETED);
601	        claim.setLockedBy(null);
602	        Claim saved = claims.saveAndFlush(claim);
603	        log(sheetId, user, person, saved);
604	        audit.recordOnCommit(record("CLAIM_DELETED", user, person, saved));
605	        rollup.recordChanges(sheetId, user, before);
606	        return saved;
