609	    /**
610	     * Restore a DELETED claim to DRAFT, only on the sheet's today it was deleted (the date of the last DELETED line of
611	     * its status log). Refused for any other status, a later day, or a claim due by a date in a closed period.
612	     */
613	    @Transactional
614	    public Claim restore(String sheetId, String user, Long id) {
615	        Claim claim = claims.findForUpdate(id, sheetId)
616	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
617	        if (claim.getStatus() != ClaimStatus.DELETED) {
618	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.DRAFT);
619	        }
620	        LocalDate deletedOn = logOf(claim).stream()
621	                .filter(l -> l.getStatus() == ClaimStatus.DELETED)
622	                .map(ClaimLog::getDate)
623	                .reduce((first, last) -> last)
624	                .orElse(null);
625	        LocalDate today = sheets.today(sheetId);
626	        if (!today.equals(deletedOn)) {
627	            throw new ClaimRestoreException(id, "a deleted claim can only be restored on the day it was deleted, "
628	                    + deletedOn);
629	        }
630	        periods.requireOpen(sheetId, claim.getDueBy());
631	        // A restored correction counts against its target again.
632	        if (claim.getCorrects() != null) {
633	            requireCorrection(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), id);
634	        }
635	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
636	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
637	        RollupService.Snapshot before = rollup.snapshot(sheetId);
638	        claim.setStatus(ClaimStatus.DRAFT);
639	        Claim saved = claims.saveAndFlush(claim);
640	        log(sheetId, user, person, saved);
641	        audit.recordOnCommit(record("CLAIM_RESTORED", user, person, saved));
642	        rollup.recordChanges(sheetId, user, before);
643	        return saved;
644	    }
