646	    /**
647	     * The reason a claim is voided with: none while the sheet's list of void reasons is empty, else the one given,
648	     * which must be on the list.
649	     */
650	    private String requireVoidReason(String sheetId, Long id, String given) {
651	        List<String> listed = voidReasons.list(sheetId).stream().map(VoidReason::getReason).toList();
652	        if (listed.isEmpty()) {
653	            return null;
654	        }
655	        String reason = given == null ? "" : given.trim();
656	        if (reason.isEmpty()) {
657	            throw new ClaimVoidReasonException(id, "choose a reason from the sheet's void reasons");
658	        }
659	        if (!listed.contains(reason)) {
660	            throw new ClaimVoidReasonException(id, reason + " is not one of the sheet's void reasons");
661	        }
662	        return reason;
663	    }
