755	    /**
756	     * Reassign as {@link #reassign(String, String, Long, Long)}; with {@code toOwnAllowed} (a bulk reassign) a claim
757	     * already the person's is moved too, listed again as its newest claim.
758	     */
759	    @Transactional
760	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId, boolean toOwnAllowed) {
761	        Claim claim = claims.findForUpdate(id, sheetId)
762	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
763	        if (!roles.may(sheetId, user, "reassign")) {
764	            throw new ClaimReassignForbiddenException(id, user);
765	        }
766	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
767	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
768	        }
769	        if (!toOwnAllowed && claim.getPersonId().equals(toPersonId)) {
770	            throw new ClaimReassignException(id, "it is already that person's");
771	        }
772	        periods.requireOpen(sheetId, claim.getDueBy());
773	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
774	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
775	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
776	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
777	        to.requireClaimable(claim.getDate());
778	        RollupService.Snapshot before = rollup.snapshot(sheetId);
779	        claim.setPersonId(to.getId());
780	        claim.setStated(false, null);
781	        claim.setListed(sheets.nextListed(sheetId));
782	        if (claim.getNumber() != null) {
783	            // A moved claim takes the next number in its sequence; its old one is never used again.
784	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
785	        }
786	        Claim saved = claims.saveAndFlush(claim);
787	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
788	                + " from=" + from.getName() + " to=" + to.getName());
789	        rollup.recordChanges(sheetId, user, before);
790	        return saved;
791	    }
