941	    /**
942	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
943	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
944	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on the sheet's today,
945	     * names the claim's number as the one it was split from. Refused for any other status, a claim due by a date in a
946	     * closed period (the new claim's own due-by is not weighed), or a user
947	     * whose role may not open a claim.
948	     */
949	    @Transactional
950	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
951	        Claim claim = claims.findForUpdate(id, sheetId)
952	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
953	        if (!roles.may(sheetId, user, "open")) {
954	            throw new ClaimActionForbiddenException(id, user, "open");
955	        }
956	        if (claim.getStatus() != ClaimStatus.OPEN) {
957	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
958	        }
959	        if (claim.isDeferredOn(sheets.today(sheetId))) {
960	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
961	        }
962	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
963	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
964	                    + claim.getAmount().toPlainString());
965	        }
966	        periods.requireOpen(sheetId, claim.getDueBy());
967	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
968	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
969	        requireUnflagged(sheetId, user, person, claim);
970	        RollupService.Snapshot before = rollup.snapshot(sheetId);
971	        claim.setAmount(claim.getAmount().subtract(amount));
972	        claim.setStated(false, null);
973	        Claim kept = claims.saveAndFlush(claim);
974	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
975	        part.setRoundingDate(kept.getRoundingDate());
976	        part.setTerms(termsFor(sheetId, person, sheets.today(sheetId)));
977	        part.setDueBy(holidays.businessDaysAfter(sheetId, kept.getDate(), part.getTerms()));
978	        part.setListed(sheets.nextListed(sheetId));
979	        part.setLateEntry(periods.softClosedOn(sheetId, part.getDueBy()));
980	        part.setStatus(ClaimStatus.OPEN);
981	        String number = nextNumber(sheetId, part.getDueBy());
982	        part.setNumber(number);
983	        part.setOpenedBy(user);
984	        part.setSplitFrom(kept.getNumber());
985	        part.setTags(kept.getTags());
986	        Claim saved = claims.saveAndFlush(part);
987	        log(sheetId, user, person, saved);
988	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
989	                + " into=" + number);
990	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
991	        rollup.recordChanges(sheetId, user, before);
992	        return saved;
993	    }
