1018	     * Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes the sheet's today.
1019	     * Refused for any other status, and for a claim already reminded on the sheet's today. While the sheet has an
1020	     * escalation gap, a claim never escalated whose previous reminder was at least that many days before the sheet's
1021	     * today is escalated: ESCALATE is written after the REMIND line.
1022	     */
1023	    @Transactional
1024	    public Claim remind(String sheetId, String user, Long id) {
1025	        Claim claim = claims.findForUpdate(id, sheetId)
1026	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
1027	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
1028	            throw new ClaimRemindException(id, "it is " + claim.getStatus()
1029	                    + ", only an OPEN or PENDING claim can be reminded");
1030	        }
1031	        LocalDate today = sheets.today(sheetId);
1032	        if (today.equals(claim.getRemindedOn())) {
1033	            throw new ClaimRemindException(id, "it was already reminded on " + today);
1034	        }
1035	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
1036	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
1037	        Integer gap = sheets.escalateAfter(sheetId);
1038	        boolean escalate = gap != null && !claim.isEscalated() && claim.getRemindedOn() != null
1039	                && !claim.getRemindedOn().plusDays(gap).isAfter(today);
1040	        claim.setRemindedOn(today);
1041	        if (escalate) {
1042	            claim.setEscalated(true);
1043	        }
1044	        Claim saved = claims.saveAndFlush(claim);
1045	        audit.recordOnCommit(record("REMIND", user, person, saved) + numberOf(saved.getNumber()));
1046	        if (escalate) {
