1052	    /**
1053	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date (its person's
1054	     * grade's own then, else the sheet's) cannot be settled or approved while it has no proof; refused then. A due of
1055	     * n/a is within any threshold. While the sheet has proof kinds, such a claim also needs a proof of each kind listed.
1056	     */
1057	    private void requireProof(String sheetId, Person person, Claim claim) {
1058	        Sheet sheet = settings.get(sheetId);
1059	        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
1060	        List<String> missing = sheet.proofKindsNeeded().stream().filter(k -> claim.proofsOf(k) == 0).toList();
1061	        if (threshold == null || (claim.getProofs() > 0 && missing.isEmpty())) {
1062	            return;
1063	        }
1064	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
1065	        if (due != null && due.compareTo(threshold) > 0) {
1066	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
1067	                    + " is above the proof threshold " + threshold.toPlainString()
1068	                    + (claim.getProofs() == 0 ? " and it has no proof"
1069	                            : " and it has no proof of kind " + String.join(", ", missing)));
1070	        }
1071	    }
