1212	    /**
1213	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
1214	     * names none. A correction may not exceed what remains of its target: the target's amount less the amounts of the
1215	     * other corrections against it that are not VOID or DELETED (the claim with the id, the one being changed, left
1216	     * out). Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null for any
1217	     * other claim.
1218	     */
1219	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects, Long id) {
1220	        if (amount.signum() >= 0) {
1221	            if (corrects != null) {
1222	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
1223	            }
1224	            return null;
1225	        }
1226	        if (corrects == null) {
1227	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
1228	        }
1229	        Claim target = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
1230	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
1231	                .orElseThrow(() -> new ClaimCorrectionException(
1232	                        "Claim " + corrects + " is not a settled claim of the same person"));
1233	        // Locking the target means two corrections of it do not both pass the check.
1234	        claims.findForUpdate(target.getId(), sheetId);
1235	        BigDecimal remaining = target.getAmount();
1236	        for (Claim other : claims.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)) {
1237	            if (corrects.equals(other.getCorrects()) && !other.getId().equals(id)
1238	                    && other.getStatus() != ClaimStatus.VOID && other.getStatus() != ClaimStatus.DELETED) {
1239	                remaining = remaining.add(other.getAmount());
1240	            }
1241	        }
1242	        if (amount.negate().compareTo(remaining) > 0) {
1243	            throw new ClaimCorrectionException("A correction of " + amount.negate().toPlainString()
1244	                    + " exceeds the " + remaining.max(BigDecimal.ZERO).toPlainString() + " that remains of claim "
1245	                    + corrects);
1246	        }
1247	        return target.getDate();
1248	    }
