1252	     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
1253	     */
1254	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
1255	        Sheet sheet = settings.get(sheetId);
1256	        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), claim.rateStamp())
1257	                .map(Rate::getPct)
1258	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getDate(), claim.getRoundingDate()))
1259	                .orElse(null);
1260	    }
