1263	     * The live due on a figure: the greater of the floor in force on the claim's date and the figure, with the late
1264	     * charge on that of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
1265	     * on the sheet's today; a correction has neither floor nor late charge, and a bound claim's figure is its due as
1266	     * shown when bound, late charge included); null (n/a) stays null.
1267	     */
1268	    private BigDecimal liveDue(String sheetId, Person person, Claim claim, BigDecimal figure) {
1269	        Sheet sheet = settings.get(sheetId);
1270	        if (claim.isBound() || claim.isCorrection()) {
1271	            return figure;
1272	        }
1273	        return sheet.liveDue(figure, claim.getStatus().isOpen()
1274	                && !claim.isWaived() && !claim.isDeferredOn(sheet.getToday()), overdueBy(sheet, person, claim), claim.getDate());
1275	    }
1276	
1277	    /** The day the claim goes overdue after: its due-by plus the grace days its person's grade has on its date. */
1278	    private static LocalDate overdueBy(Sheet sheet, Person person, Claim claim) {
1279	        return sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
1280	    }
1281	
1282	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
1283	    private static String record(String event, String user, Person person, Claim claim) {
1284	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
1285	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
1286	                + " date=" + claim.getDate();
1287	    }
