1296	     * period's own sequence (X for no period); otherwise the next sheet-wide number in the fiscal
1297	     * year of the date (<FY>-<n>).
1298	     */
1299	    public String nextNumber(String sheetId, LocalDate date) {
1300	        if (settings.get(sheetId).numbersByPeriod()) {
1301	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
