/** Claims as listed: the latest list place first. */
export function byListed(a: Claim, b: Claim): number {
  return b.listed - a.listed || b.id - a.id;
}

/**
 * DRAFT when added, then OPEN, then SETTLED; a clerk settling above the clerk limit makes it PENDING until a steward
 * approves (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a
 * SETTLED one within 7 days of its settlement. A DRAFT claim may be DELETED, counting nowhere, and restored to DRAFT on
 * the sheet's today it was deleted. A DRAFT claim whose due is above the review threshold on its date goes to REVIEW when
 * opened, counting nowhere until a steward reviews it to OPEN; it may be VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** The claim's tags, sorted; none when it has none. */
export function tagsOf(claim: Claim): string[] {
  return claim.tags === null ? [] : claim.tags.split(',');
}

/** Whether a claim is a correction (a negative amount): its due has no floor and no late charge. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
}

/**
 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
 * the sheet's today.
 */
export function counts(claim: Claim, today: string | null): boolean {
  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
}

/**
 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date. It then counts in no
 * total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export function deferred(claim: Claim, today: string | null): boolean {
  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/**
 * The status the claim had at the end of the date, as its status log records it: its last line logged on or before
 * the date; null when it has lines but none by then (it was added later). With no log at all, its status now.
 */
export function statusOn(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let found: ClaimStatus | null = null;
  for (const line of claim.log) if (line.date <= date) found = line.status;
  return found;
}

/** Whether a claim is handled as open: OPEN or PENDING. It goes overdue, bears the late charge, and a hold takes it out. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether the claim's due follows its last statement now: any claim it bound, a PENDING one included. */
export function bound(claim: Claim): boolean {
  return claim.stated;
}

/** One of a person's grades, from its from-date (yyyy-mm-dd); null from the beginning of time. */
export interface PersonGrade {
  grade: string;
  from: string | null;
}

/** The person's grade in force on the date: the one with the latest from-date on or before it. */
export function gradeOn(grades: PersonGrade[], date: string): string | undefined {
  let found: PersonGrade | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') <= (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/**
 * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when
 * its rounding date is before the sheet's policy date (the sheet's today when blank), half to even on or after it.
 */
export function roundingOf(claim: Claim, session: Session): Rounding {
  const mode = session.settingOn('rounding', claim.date);
  if (mode === 'half-up' || mode === 'half-even') return mode;
  const policy = session.policyDate() || session.today();
  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
}

/**
 * The due fixed when the claim was settled, else the due its person's last statement bound it to (as shown then, late
 * charge included), else the greater of the floor in force on its date and its figure (its amount times the rate of its
 * person's grade on its date, both in force on its date, or n/a with no rate), with the late charge on that added on top. A
 * correction has neither floor nor late charge.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
  if (claim.settledDue !== null) return claim.settledDue;
  if (bound(claim)) return claim.statedDue ?? 'n/a';
  const grade = gradeOn(grades, claim.date);
  const figure = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date, claim.rateStamp), roundingOf(claim, session));
  if (figure === 'n/a' || isCorrection(claim)) return figure;
  const base = floored(figure, session.settingOn('floor', claim.date));
  return sumDues([base, lateCharge(claim, base, grades, session)]);
}

/**
 * The day the claim goes overdue after, and its late charge counts from: its due-by plus the grace days of its person's
 * grade on its date in force on that date, else its due-by. The due-by shown stays as it is.
 */
export function overdueBy(claim: Claim, grades: PersonGrade[], session: Session): string {
  if (claim.dueBy === '') return claim.dueBy;
  const grade = gradeOn(grades, claim.date);
  const grace = grade === undefined ? null : session.settingOn('grace-' + grade, claim.date);
  return grace === null || grace === '' ? claim.dueBy : plusDays(claim.dueBy, Number(grace));
}

/**
 * For every full 30 days an OPEN claim is past its due-by (plus its grace) on the sheet's today, the late percent in
 * force on that boundary (the due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the
 * boundaries before it (compounding), each rounded like the claim's due, added up; 0.00 when it is not overdue, and on a correction.
 */
export function lateCharge(claim: Claim, figure: string, grades: PersonGrade[], session: Session): string {
  const by = overdueBy(claim, grades, session);
  const today = session.today();
  if (!isOpen(claim) || isCorrection(claim) || by === '' || today === null) return '0.00';
  if (deferred(claim, today) || claim.waived) return '0.00';
  const days = Math.round((Date.parse(today) - Date.parse(by)) / 86_400_000);
  const charges: string[] = [];
  for (let boundary = 1; boundary <= Math.floor(days / 30); boundary++) {
    const pct = session.settingOn('late-pct', plusDays(by, 30 * boundary));
    if (pct !== null) charges.push(percentOf(sumDues([figure, ...charges]), pct, 1, roundingOf(claim, session)));
  }
  return sumDues(charges);
}

/** The yyyy-mm-dd date the days after the date. */
export function plusDays(date: string, days: number): string {
  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
}

/** Whether the claim's due is fixed, by settling or by a statement, rather than worked out from the rates. */
export function dueFixed(claim: Claim): boolean {
  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
}

/** Whether the claim is OPEN or PENDING, not deferred, and its due-by plus its grace is before the sheet's today. */
export function overdue(claim: Claim, grades: PersonGrade[], session: Session): boolean {
  const today = session.today();
  return isOpen(claim) && today !== null && overdueBy(claim, grades, session) < today && !deferred(claim, today);
}

type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore' | 'review';

/** Sums amounts with two decimals exactly, in whole cents. */
export function sumAmounts(amounts: string[]): string {
  const cents = amounts.reduce((total, a) => total + Math.round(Number(a) * 100), 0);
  return (cents / 100).toFixed(2);
}

// One person's claims, newest first, each with its due, and the form that adds a claim or, once a claim's editor is
// opened, saves that claim. Rendered as a table cell inside the person's row.
@Component({
  selector: 'td[app-claims]',
  imports: [FigurePipe],
  template: `
    <form (submit)="submit($event)">
      <label [for]="fieldId('amount')">Amount</label>
export interface OlderRate {
  pct: string;
  to: string | null;
  forwardAfter: number | null;
}

/** Whether a claim with the stamp sees a setting with the mark; any does without a stamp. */
function seen(forwardAfter: number | null, stamp: number | undefined): boolean {
  return forwardAfter === null || stamp === undefined || stamp > forwardAfter;
}

/** The rate as the claim with the stamp sees it: itself, else its newest older version it sees; undefined with none. */
function seenBy(rate: Rate, stamp: number | undefined): Rate | undefined {
  if (seen(rate.forwardAfter, stamp)) return rate;
  const older = (rate.older ?? []).find((v) => seen(v.forwardAfter, stamp));
  return older === undefined ? undefined : { ...rate, pct: older.pct, to: older.to, forwardAfter: older.forwardAfter };
}

/**
 * The percent of the grade's rate in force on the date: the one with the latest from-date on or
 * before it, an undated rate counting as from the beginning of time; undefined when the date is
 * before every rate, or after that rate's to-date. With none of the sheet's own in force, the
 * parent sheet's, then its parent's, and so on (nearest level first). For a claim, given its rateStamp: a
 * forward-only rate saved before the claim was added is left out, falling back on its older version the claim sees.
 */
export function rateOn(rates: Rate[], grade: string, date: string, stamp?: number): string | undefined {
  const levels = [...new Set(rates.map((r) => r.level))].sort((a, b) => a - b);
  for (const level of levels) {
    const seenRates = rates.flatMap((r) => (r.level === level ? (seenBy(r, stamp) ?? []) : []));
    const pct = rateOnLevel(seenRates, grade, date);
    if (pct !== undefined) return pct;
  }
  return undefined;
}

function rateOnLevel(rates: Rate[], grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found === undefined || (found.to !== null && found.to < date) ? undefined : found.pct;
}

/** Hundredths of a unit in a decimal with at most two decimals, maybe negative ("10.25" is 1025n, "-0.30" is -30n). */
function hundredths(value: string): bigint {
  const trimmed = value.trim();
  const negative = trimmed.startsWith('-');
  const [whole, fraction = ''] = (negative ? trimmed.slice(1) : trimmed).split('.');
  const size = BigInt(whole || '0') * 100n + BigInt((fraction + '00').slice(0, 2));
  return negative ? -size : size;
}

/** Hundredths of a unit as a decimal with two decimals ("-30n" is "-0.30"). */
function decimalOf(cents: bigint): string {
  const size = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${size / 100n}.${(size % 100n).toString().padStart(2, '0')}`;
}

/** How a figure rounds a half cent: up (away from zero), or to the even cent. */
export type Rounding = 'half-up' | 'half-even';

/** An amount times a percent, divided by 100 and rounded to two decimals as given; n/a with no rate. */
export function dueOf(amount: string, pct: string | undefined, rounding: Rounding = 'half-even'): string {
  if (pct === undefined) return 'n/a';
  return percentOf(amount, pct, 1, rounding);
}

/** The pct percent of the amount, times the given count, rounded to cents, a half up or to the even cent. */
export function percentOf(amount: string, pct: string, times: number, rounding: Rounding = 'half-even'): string {
  // cents times hundredths of a percent are millionths of a unit: round them to cents.
  // A negative amount (a correction) rounds as its size does, so a half goes away from zero, or to the even cent.
  const signed = hundredths(amount) * hundredths(pct) * BigInt(times);
  const millionths = signed < 0n ? -signed : signed;
  const rest = millionths % 10000n;
  let cents = millionths / 10000n;
  if (rest > 5000n || (rest === 5000n && (rounding === 'half-up' || cents % 2n === 1n))) cents += 1n;
  return decimalOf(signed < 0n ? -cents : cents);
}

/** The due raised to the floor when below it; n/a, or no floor, leaves it as it is. */
export function floored(due: string, floor: string | null): string {
  if (due === 'n/a' || floor === null) return due;
  return hundredths(due) < hundredths(floor) ? floor : due;
}

/** The due-total held down to the cap when above it; n/a, or no cap, leaves it as it is. */
export function capped(dueTotal: string, cap: string | null): string {
  if (dueTotal === 'n/a' || cap === null) return dueTotal;
  return hundredths(dueTotal) > hundredths(cap) ? cap : dueTotal;
}

/** How far the due-total is above the cap: 0.00 when it is not, or is n/a, or there is no cap. */
export function excessOver(dueTotal: string, cap: string | null): string {
  if (dueTotal === 'n/a' || cap === null || hundredths(dueTotal) <= hundredths(cap)) return '0.00';
  return decimalOf(hundredths(dueTotal) - hundredths(cap));
}

/** The figure less the one before it, exactly to two decimals, with a minus sign when lower. */
export function changeFrom(figure: string, before: string): string {
  return decimalOf(hundredths(figure) - hundredths(before));
}

/** Adds dues with two decimals exactly, a correction's negative ones too, skipping the n/a ones. */
export function sumDues(dues: string[]): string {
  return decimalOf(dues.filter((d) => d !== 'n/a').reduce((total, d) => total + hundredths(d), 0n));
}

/**
 * Each figure times its share divided by 100, added up exactly and rounded half to even to two decimals, a negative
 * total as its size does; skipping the n/a figures.
 */
export function sumShared(figures: { figure: string; share: string }[]): string {
  // cents times hundredths of a percent are millionths of a unit: add them up, then round to cents.
  const signed = figures
    .filter((f) => f.figure !== 'n/a')
    .reduce((total, f) => total + hundredths(f.figure) * hundredths(f.share), 0n);
  const millionths = signed < 0n ? -signed : signed;
  const rest = millionths % 10000n;
  let cents = millionths / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return decimalOf(signed < 0n ? -cents : cents);
}

/** As {@link sumDues}, but leaving out the single highest and lowest figure when there are three or more. */
export function trimmedSumDues(dues: string[]): string {
  const figures = dues.filter((d) => d !== 'n/a').map(hundredths);
  if (figures.length < 3) return sumDues(dues);
  const sorted = [...figures].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return decimalOf(sorted.slice(1, -1).reduce((total, d) => total + d, 0n));
}

// The rate in force on the sheet's today for each grade, every rate with its from-date, and the form
// that sets a grade's rate from a date.
@Component({
  selector: 'app-rates',
  imports: [FigurePipe],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** A dated setting's value (two decimals or whole days; null: none) from its from-date (yyyy-mm-dd). */
export interface DatedValue {
  from: string;
  value: string | null;
}

/** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
const STARTING: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  viewer: boolean;
  lastSettleBatch: number | null;
  steward: boolean;
}

// The signed-in user and the active sheet. Signing in only takes a name; the name is sent with
// every request in the X-User header.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it. */
  readonly today = signal<string | null>(null);
  /** Whether the active sheet is archived: everything stays visible and every change is refused. */
  readonly archived = signal(false);
  /** Whether the signed-in user is a viewer of the active sheet, as of its last load: they may change nothing. */
  readonly viewer = signal(false);
  /** Whether the signed-in user is a steward of the active sheet (in their own right or by delegation), as of its last
   *  load. */
  readonly steward = signal(false);
  /** The number of the active sheet's last bulk settle batch; null while there has been none. */
  readonly lastSettleBatch = signal<number | null>(null);
  /** Whether retired people are listed: off when the screen opens, and left as it is by loading a sheet. */
  readonly showRetired = signal(false);
  /** The date this screen shows the sheet as of (yyyy-mm-dd): it stands in for the sheet's today and every change is
   *  refused; null shows the sheet as it stands. It belongs to this screen and is kept when another sheet is loaded. */
  readonly asOf = signal<string | null>(null);
  /** Counts completed sheet loads, so the screen re-reads the sheet's data even for the same id. */
  readonly loaded = signal(0);
  /** Every value recorded of each dated setting of the active sheet (clerk-limit, floor, terms, terms-A, terms-B,
   *  terms-C, late-pct, cap, proof-threshold, note-threshold, review-threshold, rounding), from-date first to last; null until the settings are read. */
  readonly dated = signal<Record<string, DatedValue[]> | null>(null);
  /** The active sheet's floor (two decimals) in force on its today: a live due is at least it; null until the settings are read. */
  readonly floor = computed(() => this.settingOn('floor', this.today()));
  /** The active sheet's terms in force on its today: a claim of a grade without its own is due by its date plus these many days; null until the settings are read. */
  readonly terms = computed(() => {
    const terms = this.settingOn('terms', this.today());
    return terms === null ? null : Number(terms);
  });
  /** The active sheet's late percent (two decimals) in force on its today: an overdue claim's due gains it of its figure every full 30 days. */
  readonly latePct = computed(() => this.settingOn('late-pct', this.today()));
  /** The active sheet's policy date (yyyy-mm-dd): a claim dated before it rounds half up, on or after it half to even;
   *  blank means the sheet's today; null until the settings are read. */
  readonly policyDate = signal<string | null>(null);
  /** The active sheet's entry date (yyyy-mm-dd): while set, the default date of a new claim; blank means off (the
   *  sheet's today); null until the settings are read. */
  readonly entryDate = signal<string | null>(null);
  /** The active sheet's pot (two decimals), shared out over each balanced pool's members by their shares; blank means
   *  none; null until the settings are read. */
  readonly pot = signal<string | null>(null);
  /** The active sheet's parent sheet id, whose rates a grade with none in force falls back on; blank means none;
   *  null until the settings are read. */
  readonly parent = signal<string | null>(null);
  /** The active sheet's review SLA in days: a REVIEW claim whose review day plus it is before the sheet's today is
   *  late; blank means none; null until the settings are read. */
  readonly reviewSla = signal<string | null>(null);
  /** The default date of a new claim: the entry date while it is set, else the sheet's today. */
  readonly newClaimDate = computed(() => this.entryDate() || this.today());
  /** The active sheet's cap (two decimals) in force on its today: a person's due-total is at most it; null when there
   *  is none or until the settings are read. */
  readonly cap = computed(() => this.settingOn('cap', this.today()));
  private loads = 0;
  /** The number of sheet loads waiting for their answer. */
  private loading = 0;
  /** The completed load whose data each part of the screen last showed, by part. */
  private readonly shownLoads: Record<string, number> = {};

  signIn(name: string): void {
    this.user.set(name);
    this.asOf.set(null);
    this.sheet.set(null);
    this.today.set(null);
  }

  /**
   * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
   * sheet's starting value; null when that is none, or until the settings are read.
   */
  settingOn(key: string, date: string | null): string | null {
    const dated = this.dated();
    if (dated === null || date === null) return null;
    let value: string | null = STARTING[key] ?? null;
    for (const d of dated[key] ?? []) {
      if (d.from <= date) value = d.value;
    }
    return value;
  }

  /** Whether a claim is late for review: in REVIEW, with its review day plus the review SLA before the sheet's today. */
  reviewLate(claim: { status: string; reviewOn: string | null }): boolean {
    const sla = this.reviewSla();
    const today = this.today();
    if (claim.status !== 'REVIEW' || !sla || claim.reviewOn === null || today === null) return false;
    const [y, m, d] = claim.reviewOn.split('-').map(Number);
    const limit = new Date(Date.UTC(y, m - 1, d + Number(sla))).toISOString().slice(0, 10);
    return limit < today;
  }

  /** Request options carrying the signed-in user. */
  headers(): { headers: Record<string, string> } {
    return { headers: { 'X-User': this.user() ?? '' } };
  }

  /** Load a sheet by id; an id never used before starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const load = ++this.loads;
    this.loading++;
    const loaded = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    ).finally(() => this.loading--);
    // A later load wins over a slower earlier one.
    if (load === this.loads) {
      this.show(loaded);
      this.loaded.update((n) => n + 1);
    }
  }

  /** Record that the part of the screen now shows the data it read for the completed load. */
  shown(part: string, load: number): void {
    this.shownLoads[part] = load;
  }

  /**
   * Resolves once no sheet load is waiting for its answer and each of the parts shows the data read for the latest
   * completed load (so a figure taken from the screen is the sheet as it now stands, or as of the as-of date).
   */
  async settled(...parts: string[]): Promise<void> {
    // A part whose read failed never catches up: after a while, take the screen as it is.
    for (let waited = 0; waited < 10_000; waited += 20) {
      if (this.loading === 0 && parts.every((part) => this.shownLoads[part] === this.loaded())) return;
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
  }

  /** Show the active sheet as of the date (null: as it stands), re-reading all of it. */
  async setAsOf(date: string | null): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet loaded.');
    const was = this.asOf();
    this.asOf.set(date);
    try {
      await this.loadSheet(id);
    } catch (e) {
      this.asOf.set(was);
      throw e;
    }
  }

  /** Change the active sheet's today. */
  async setToday(today: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.put<SheetView>(
        `/api/sheets/${encodeURIComponent(id)}/today`,
        { today },
        { headers: { 'X-User': this.user() ?? '' } },
      ),
    );
    if (this.sheet() === saved.id) this.show(saved);
  }

  /** Archive the active sheet: a steward may; every change to it is refused from then on. */
  async archive(): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === saved.id) this.show(saved);
  }

  /** Clone the active sheet to another id never used: a steward may. */
  async cloneSheet(to: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet loaded.');
    await firstValueFrom(
      this.http.post<SheetView>(
        `/api/sheets/${encodeURIComponent(id)}/clone`,
        { to },
        { headers: { 'X-User': this.user() ?? '' } },
      ),
    );
  }

  private show(view: SheetView): void {
    this.sheet.set(view.id);
    this.today.set(view.today);
    this.archived.set(view.archived);
    this.viewer.set(view.viewer);
    this.steward.set(view.steward);
    this.lastSettleBatch.set(view.lastSettleBatch);
  }
}

